def update(self) -> bool:
    """Update recording state. Returns True if recording finished."""
    if not self._enabled:
        return False
    if self._started_at is None:
        self._started_at = time.time()
    if time.time() - self._started_at > self._stop_time:
        self._finish()
        return True
    return False

